import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.service.query.ProductQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class StyleBidCommandService {

    private final StyleBidRepository saleBidRepository;
    private final ProductQueryService userQueryService;
    private final UserSizeQueryService productSizeQueryService;
    private final StyleCommandService saleCommandService;
    private final FaqBidQueryService orderBidQueryService;
    @Transactional
    public StyleBid createSaleBid(String sellerEmail, Long productSizeId, int bidPrice,
                                 String returnAddress, String postalCode, String receiverPhone
                                , boolean isWarehouseStorage) {

        Product seller = userQueryService.findByEmail(sellerEmail);


        UserSize productSize = productSizeQueryService.findById(productSizeId)
                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));


        Style sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);


        StyleBid saleBid = StyleBid.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .sale(sale)
                .build();


        saleBid = saleBidRepository.save(saleBid);


        sale.assignSaleBid(saleBid);


        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Style sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);

        FaqBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));



        StyleBid saleBid = StyleBid.builder()
                .seller(sale.getSeller())
                .productSize(sale.getProductSize())
                .bidPrice(orderBid.getBidPrice())
                .status(BidStatus.MATCHED)
                .sale(sale)
                .order(orderBid.getOrder())
                .build();


        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid);


        saleBidRepository.save(saleBid);


        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {

        StyleBid saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));


        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }


        if (saleBid.getSale() != null) {
            saleCommandService.deleteSale(saleBid.getSale().getId());
        }


        saleBidRepository.delete(saleBid);
    }
}
